import json
grid=[]
pts={3:[9],11:[8],12:[4,7],14:[6],18:[2],21:[5]}
for r in range(25):
 row=[0]*19
 if r==0:
  for c in range(2,10): row[c]=8
 if r==24:
  for c in range(11,19): row[c]=8
 # paired-track lines from the opposite border, preserve the border itself
 if r<24:
  for c in range(2,10): row[c+9]=7
 # ray from top segment down to each marker
 for rr,cs in pts.items():
  if 1 <= r < rr:
   for c in cs: row[c]=7
 # markers recolored 4
 for c in pts.get(r,[]): row[c]=4
 grid.append(row)
print(json.dumps(grid,separators=(',',':')))

